def resolve(path, cwd, links):
    # Check if path is absolute, otherwise make it relative to cwd
    if path.startswith('/'):
        current = '/'
        parts = path.split('/')[1:]  # Skip empty string before first '/'
    else:
        current = cwd
        parts = path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(parts):
        component = parts[i]
        i += 1

        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            # Move to parent directory
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            # If current is '/', it stays '/'
            continue

        # Append the component to current path
        if current == '/':
            next_path = '/' + component
        else:
            next_path = current + '/' + component

        # Check if this path is a symlink
        if next_path in links:
            # Follow the link
            link_count += 1
            if link_count > max_links:
                return None  # Too many links followed

            target = links[next_path]

            # Resolve the target relative to the directory containing the link
            if target.startswith('/'):
                # Absolute target
                current = '/'
                target_parts = target.split('/')[1:]  # Skip empty string before first '/'
            else:
                # Relative target - relative to directory containing the link
                if next_path == '/':
                    link_dir = '/'
                else:
                    link_dir = next_path.rsplit('/', 1)[0]
                    if link_dir == '':
                        link_dir = '/'
                current = link_dir
                target_parts = target.split('/')

            # Insert remaining components after target parts
            parts = target_parts + parts[i:]
            i = 0  # Start processing from the beginning of the new parts
        else:
            # Not a symlink, just update current
            current = next_path

    # Ensure no trailing slash except for '/'
    if current == '':
        return None  # Should not happen if cwd is canonical

    return current

